import{describe,it,expect}from"vitest";import{RBI_HISTORY_TIMELINE,RBI_CORE_FUNCTIONS,MPC_STRUCTURE_INFO,MONETARY_TOOLS_DATA,CURRENCY_LOCATIONS,INFLATION_CONTROL_MECHANISM,simulateRepoRateImpact,calculateBankReserves,filterMonetaryTools,getMonetaryPolicyStats}from"../../frontend/rbi-explorer/rbi-explorer.js";describe("RBI History Timeline & Core Functions Integrity",()=>{it("contains at least 7 historical milestones starting from 1926 Hilton Young Commission",()=>{expect(RBI_HISTORY_TIMELINE.length).toBeGreaterThanOrEqual(7),expect(RBI_HISTORY_TIMELINE[0].year).toBe("1926")}),it("every historical milestone contains year, title, era, summary, and details",()=>{RBI_HISTORY_TIMELINE.forEach((e,t)=>{expect(e,`Milestone at index ${t} missing year`).toHaveProperty("year"),expect(e,`Milestone at index ${t} missing title`).toHaveProperty("title"),expect(e,`Milestone at index ${t} missing era`).toHaveProperty("era"),expect(e,`Milestone at index ${t} missing summary`).toHaveProperty("summary"),expect(e,`Milestone at index ${t} missing details`).toHaveProperty("details"),expect(typeof e.title).toBe("string"),expect(e.title.trim().length).toBeGreaterThan(0),expect(typeof e.summary).toBe("string"),expect(e.summary.trim().length).toBeGreaterThan(0)})}),it("defines core central banking functions (Monetary Authority, Banking Regulator, Forex Manager, Currency Issuer)",()=>{expect(RBI_CORE_FUNCTIONS.length).toBeGreaterThanOrEqual(6);const e=RBI_CORE_FUNCTIONS.map(e=>e.id);expect(e).toContain("monetary-authority"),expect(e).toContain("regulator-banking"),expect(e).toContain("forex-manager"),expect(e).toContain("currency-issuer"),expect(e).toContain("banker-government"),expect(e).toContain("banker-banks")})}),describe("Monetary Policy Committee & Tools Dataset Integrity",()=>{it("defines 6-member MPC composition and 4% inflation target mandate",()=>{expect(MPC_STRUCTURE_INFO.totalMembers).toBe(6),expect(MPC_STRUCTURE_INFO.targetInflation).toBe("4.0%"),expect(MPC_STRUCTURE_INFO.toleranceBand).toContain("4% ± 2%")}),it("defines key monetary tools (Repo Rate, SDF, MSF, CRR, SLR)",()=>{expect(MONETARY_TOOLS_DATA.length).toBe(5);const e=MONETARY_TOOLS_DATA.map(e=>e.name.toLowerCase());expect(e.some(e=>e.includes("repo rate"))).toBe(!0),expect(e.some(e=>e.includes("cash reserve ratio"))).toBe(!0),expect(e.some(e=>e.includes("statutory liquidity ratio"))).toBe(!0)}),it("defines currency printing presses and coin mint locations",()=>{expect(CURRENCY_LOCATIONS.printingPresses.length).toBe(4),expect(CURRENCY_LOCATIONS.mintLocations.length).toBe(4),expect(CURRENCY_LOCATIONS.securityFeatures.length).toBeGreaterThanOrEqual(4)})}),describe("Policy Repo Rate Simulator Math",()=>{it("calculates home loan & deposit interest rate estimates based on repo rate input",()=>{const e=simulateRepoRateImpact(6.5);expect(e.repoRate).toBe("6.50"),expect(e.estimatedHomeLoanRate).toBe("8.75%"),expect(e.estimatedFixedDepositRate).toBe("7.25%"),expect(e.liquidityCondition).toBe("Balanced Liquidity")}),it("identifies tight liquidity and inflation cooling when repo rate is high (e.g. 8.0%)",()=>{const e=simulateRepoRateImpact(8);expect(e.liquidityCondition).toContain("Tight Interbank Liquidity"),expect(e.consumerDemandImpact).toContain("Subdued Consumer Borrowing")}),it("identifies surplus liquidity and demand stimulus when repo rate is low (e.g. 4.5%)",()=>{const e=simulateRepoRateImpact(4.5);expect(e.liquidityCondition).toContain("Surplus System Liquidity"),expect(e.consumerDemandImpact).toContain("High Borrowing")})}),describe("CRR & SLR Reserve Calculator Math",()=>{it("correctly calculates CRR cash, SLR G-Secs, and Lendable amounts for ₹1,00,000 Crore deposits",()=>{const e=calculateBankReserves(1e5,4.5,18);expect(e.crrAmount).toBe(4500),expect(e.slrAmount).toBe(18e3),expect(e.totalReserved).toBe(22500),expect(e.lendableAmount).toBe(77500),expect(e.lendablePercentage).toBe("77.5")}),it("handles zero or custom deposit inputs safely",()=>{const e=calculateBankReserves(0,4.5,18);expect(e.crrAmount).toBe(0),expect(e.slrAmount).toBe(0),expect(e.lendableAmount).toBe(0)})}),describe("Filtering & Policy Stats Helpers",()=>{it("filters monetary tools by type",()=>{const e=filterMonetaryTools(MONETARY_TOOLS_DATA,"Reserve Ratio");expect(e.length).toBe(2);const t=filterMonetaryTools(MONETARY_TOOLS_DATA,"all");expect(t.length).toBe(5)}),it("returns valid monetary policy summary statistics",()=>{const e=getMonetaryPolicyStats();expect(e.repoRate).toBe("6.50%"),expect(e.crrRate).toBe("4.50%"),expect(e.slrRate).toBe("18.00%")})});